const body = $json.body || $json;
const consulta = (body.consulta || '').toLowerCase().trim();

const comandos = ['libros_para_rebajar','libros_sin_marketing','generos_mas_rentables','libros_parados_90','resumen_inventario','stock_por_genero','ventas_por_plataforma','tickets_abiertos','margen_bajo','ayuda'];

let comando = null;
for (const c of comandos) {
  if (consulta.includes(c) || consulta === c) { comando = c; break; }
}

if (!comando) {
  if (consulta.includes('rebaj') || consulta.includes('descont')) comando = 'libros_para_rebajar';
  else if (consulta.includes('marketing') || consulta.includes('promocion')) comando = 'libros_sin_marketing';
  else if (consulta.includes('rentab') || consulta.includes('margen')) comando = 'generos_mas_rentables';
  else if (consulta.includes('parado') || consulta.includes('90')) comando = 'libros_parados_90';
  else if (consulta.includes('inventario') || consulta.includes('stock')) comando = 'resumen_inventario';
  else if (consulta.includes('genero')) comando = 'stock_por_genero';
  else if (consulta.includes('plataforma')) comando = 'ventas_por_plataforma';
  else if (consulta.includes('ticket') || consulta.includes('soporte')) comando = 'tickets_abiertos';
  else if (consulta.includes('margen bajo')) comando = 'margen_bajo';
  else comando = 'ayuda';
}

return [{ json: { comando: comando, consultaOriginal: consulta } }];

const comando = $('Interpretar Consulta').first().json.comando;
const inventory = $('Consultar Inventario').first().json.results || $('Consultar Inventario').first().json.data || [];
const sales = $('Consultar Ventas').first().json.results || $('Consultar Ventas').first().json.data || [];
const support = $('Consultar Soporte').first().json.results || $('Consultar Soporte').first().json.data || [];

const now = new Date();
const dayMs = 86400000;

const books = inventory.map(b => {
  const p = b.properties || {};
  return {
    title: p.Nombre?.title?.[0]?.plain_text || '',
    author: p.Autor?.rich_text?.[0]?.plain_text || '',
    genre: p.Genero?.select?.name || 'Otros',
    estadoPublicacion: p['Estado publicacion']?.select?.name || '',
    coste: p.Coste?.number || 0,
    precioVenta: p['Precio venta']?.number || 0,
    fechaEntrada: p['date:Fecha entrada:start'] || '',
    marketingGenerado: p['Marketing generado'] === '__YES__',
    sku: p.SKU?.number || p.SKU?.formula_string || ''
  };
});

let respuesta = '';

switch (comando) {
  case 'libros_para_rebajar': {
    const rebajar = books.filter(b => {
      if (b.estadoPublicacion !== 'Publicado' || !b.fechaEntrada) return false;
      const dias = Math.floor((now - new Date(b.fechaEntrada)) / dayMs);
      return dias > 30;
    }).map(b => {
      const dias = Math.floor((now - new Date(b.fechaEntrada)) / dayMs);
      return `- ${b.title} (${b.author}) - ${dias} dias - ${b.precioVenta} eur`;
    });
    respuesta = rebajar.length > 0 ? `Libros candidatos a rebaja (${rebajar.length}):\n\n${rebajar.join('\n')}` : 'No hay libros que necesiten rebaja.';
    break;
  }
  case 'libros_sin_marketing': {
    const sin = books.filter(b => b.estadoPublicacion === 'Publicado' && !b.marketingGenerado);
    respuesta = sin.length > 0 ? `Libros sin marketing (${sin.length}):\n\n${sin.map(b => `- ${b.title} (${b.author}) - ${b.precioVenta} eur`).join('\n')}` : 'Todos los libros tienen marketing generado.';
    break;
  }
  case 'generos_mas_rentables': {
    const gm = {};
    sales.forEach(s => {
      const p = s.properties || {};
      const g = p.Genero?.select?.name || 'Otros';
      const margen = (p['Precio venta']?.number || 0) - (p.Coste?.number || 0);
      if (!gm[g]) gm[g] = { margen: 0, count: 0 };
      gm[g].margen += margen;
      gm[g].count++;
    });
    const sorted = Object.entries(gm).sort((a, b) => b[1].margen - a[1].margen);
    respuesta = `Generos mas rentables:\n\n${sorted.map(([g, d]) => `- ${g}: ${d.margen.toFixed(2)} eur (${d.count} ventas)`).join('\n')}`;
    break;
  }
  case 'libros_parados_90': {
    const parados = books.filter(b => {
      if (b.estadoPublicacion !== 'Publicado' || !b.fechaEntrada) return false;
      return Math.floor((now - new Date(b.fechaEntrada)) / dayMs) > 90;
    });
    respuesta = parados.length > 0 ? `Libros +90 dias (${parados.length}):\n\n${parados.map(b => `- ${b.title} (${b.author}) - ${b.precioVenta} eur`).join('\n')}\n\nSugerencia: rebajar 20% o retirar.` : 'No hay libros parados mas de 90 dias.';
    break;
  }
  case 'resumen_inventario': {
    const disp = books.filter(b => b.estadoPublicacion === 'Publicado');
    const res = books.filter(b => b.estadoPublicacion === 'Reservado');
    const vend = books.filter(b => b.estadoPublicacion === 'Vendido');
    const valor = disp.reduce((s, b) => s + b.precioVenta, 0);
    const coste = disp.reduce((s, b) => s + b.coste, 0);
    respuesta = `Resumen de inventario:\n\n- Disponibles: ${disp.length} (valor: ${valor.toFixed(2)} eur)\n- Reservados: ${res.length}\n- Vendidos: ${vend.length}\n- Coste stock: ${coste.toFixed(2)} eur\n- Margen potencial: ${(valor - coste).toFixed(2)} eur`;
    break;
  }
  case 'stock_por_genero': {
    const gc = {};
    books.filter(b => b.estadoPublicacion === 'Publicado').forEach(b => { gc[b.genre] = (gc[b.genre] || 0) + 1; });
    const sorted = Object.entries(gc).sort((a, b) => b[1] - a[1]);
    respuesta = `Stock por genero:\n\n${sorted.map(([g, n]) => `- ${g}: ${n} libros`).join('\n')}`;
    break;
  }
  case 'ventas_por_plataforma': {
    const pc = {};
    sales.forEach(s => {
      const p = s.properties || {};
      const plat = p.Plataforma?.select?.name || 'Otros';
      const precio = p['Precio venta']?.number || 0;
      if (!pc[plat]) pc[plat] = { count: 0, total: 0 };
      pc[plat].count++;
      pc[plat].total += precio;
    });
    respuesta = `Ventas por plataforma:\n\n${Object.entries(pc).map(([p, d]) => `- ${p}: ${d.count} ventas, ${d.total.toFixed(2)} eur`).join('\n')}`;
    break;
  }
  case 'tickets_abiertos': {
    const abiertos = support.filter(t => {
      const p = t.properties || {};
      const estado = p['Estado ticket']?.select?.name || '';
      return estado === 'Nuevo' || estado === 'En revision';
    });
    respuesta = abiertos.length > 0 ? `Tickets abiertos (${abiertos.length}):\n\n${abiertos.map(t => { const p = t.properties || {}; return `- ${p.Asunto?.title?.[0]?.plain_text || 'Sin asunto'} (${p.Prioridad?.select?.name || 'Media'})`; }).join('\n')}` : 'No hay tickets abiertos.';
    break;
  }
  case 'margen_bajo': {
    const bajo = books.filter(b => {
      if (b.estadoPublicacion !== 'Publicado' || b.precioVenta === 0) return false;
      return (((b.precioVenta - b.coste) / b.precioVenta) * 100) < 40;
    });
    respuesta = bajo.length > 0 ? `Libros con margen bajo <40% (${bajo.length}):\n\n${bajo.map(b => `- ${b.title} - Coste: ${b.coste} eur, Precio: ${b.precioVenta} eur`).join('\n')}` : 'Todos los libros tienen margen >= 40%.';
    break;
  }
  default: {
    respuesta = `Copiloto de Segunda Vuelta Libros\n\nComandos disponibles:\n- libros_para_rebajar\n- libros_sin_marketing\n- generos_mas_rentables\n- libros_parados_90\n- resumen_inventario\n- stock_por_genero\n- ventas_por_plataforma\n- tickets_abiertos\n- margen_bajo\n\nEscribe el comando o una pregunta natural (ej: 'que libros rebajar?').`;
  }
}

return [{ json: { respuesta: respuesta, comando: comando } }];
